const crypto = require('crypto');

const TOLERANCE_SECONDS = 300;
const secret = $env.N8N_WEBHOOK_SECRET;
const headers = $input.first().json.headers || {};
const raw = (await this.helpers.getBinaryDataBuffer(0, 'data')).toString('utf8');

const reject = (reason) => [{ json: { valid: false, reason } }];

if (!secret) return reject('secret not configured');
const parts = Object.fromEntries(
  String(headers['x-lendloop-signature'] || '').split(',').map((p) => {
    const i = p.indexOf('=');
    return [p.slice(0, i).trim(), p.slice(i + 1).trim()];
  }),
);
const timestamp = Number(parts.t);
if (!parts.v1 || !Number.isInteger(timestamp)) return reject('missing signature');
if (Math.abs(Date.now() / 1000 - timestamp) > TOLERANCE_SECONDS) return reject('stale timestamp');

const expected = crypto.createHmac('sha256', secret).update(`${timestamp}.${raw}`).digest();
const given = Buffer.from(parts.v1, 'hex');
if (given.length !== expected.length || !crypto.timingSafeEqual(given, expected)) return reject('bad signature');

const payload = JSON.parse(raw);
if (headers['x-lendloop-delivery-id'] !== payload.deliveryId) return reject('delivery id mismatch');

return [{ json: { valid: true, payload } }];

const esc = (s) => String(s ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const fmt = (iso) => new Date(`${iso}T00:00:00Z`).toLocaleDateString('en-US', { month: 'short', day: 'numeric', timeZone: 'UTC' });
const range = (a, b) => (a === b ? fmt(a) : `${fmt(a)} – ${fmt(b)}`);
const appUrl = ($env.APP_URL || '').replace(/\/$/, '');

function layout({ heading, lines, cta, href, tag }) {
  const body = lines.map((l) => `<p style="margin:0 0 12px;font-size:16px;line-height:1.5;color:#1B1B1B">${l}</p>`).join('');
  return `<!doctype html><html><body style="margin:0;background:#F4F1EA;font-family:Barlow,Arial,sans-serif">
<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#F4F1EA;padding:24px 12px"><tr><td align="center">
<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="max-width:520px">
<tr><td style="background:#1B1B1B;padding:14px 20px;border-radius:8px 8px 0 0;font:700 20px 'Barlow Condensed',Arial Narrow,Arial,sans-serif;letter-spacing:.06em;color:#F4C20D">LENDLOOP</td></tr>
<tr><td style="background:#ffffff;padding:24px 20px;border:1px solid #E2DACB;border-top:0;border-radius:0 0 8px 8px">
<span style="display:inline-block;background:#E8D2A6;border:1px solid #9E7A4D;border-radius:3px 10px 10px 3px;padding:2px 10px;font:700 12px Arial,sans-serif;letter-spacing:.06em;text-transform:uppercase;color:#1B1B1B">${esc(tag)}</span>
<h1 style="margin:14px 0 12px;font:700 26px/1.15 'Barlow Condensed',Arial Narrow,Arial,sans-serif;text-transform:uppercase;color:#1B1B1B">${heading}</h1>
${body}
<p style="margin:20px 0 0"><a href="${href}" style="display:inline-block;background:#F4C20D;color:#1B1B1B;text-decoration:none;font-weight:700;padding:12px 20px;border-radius:6px">${esc(cta)}</a></p>
</td></tr>
<tr><td style="padding:14px 4px;font-size:12px;color:#5C5548">You get this because you lend or borrow on LendLoop. We only email you about your own loans.</td></tr>
</table></td></tr></table></body></html>`;
}
const toText = ({ heading, lines, cta, href }) =>
  [heading, '', ...lines.map((l) => l.replace(/<[^>]+>/g, '').replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&quot;/g, '"').replace(/&#39;/g, "'")), '', `${cta}: ${href}`].join('\n');

const p = $input.first().json.payload;
const who = esc(p.counterpart?.firstName || 'A neighbor');
const tool = `<strong>${esc(p.toolName)}</strong>`;
const dates = esc(range(p.startDate, p.endDate));
const hi = `Hi ${esc(p.recipient.firstName)},`;

const templates = {
  requested: {
    subject: `${p.counterpart?.firstName || 'A neighbor'} wants to borrow your ${p.toolName}`,
    tag: 'New request', heading: 'Someone wants to borrow your tool',
    lines: [hi, `${who} asked to borrow your ${tool} for ${dates}.`, 'Approve or decline it from Incoming.'],
    cta: 'Answer the request', path: '/app/incoming',
  },
  approved: {
    subject: `Approved: ${p.toolName}, ${range(p.startDate, p.endDate)}`,
    tag: 'Approved', heading: "You're borrowing it",
    lines: [hi, `${who} approved your request for the ${tool}, ${dates}.`, 'Sort out pickup with them, and bring it back by the last day.'],
    cta: 'See your requests', path: '/app/requests',
  },
  declined: {
    subject: `Not this time: ${p.toolName}`,
    tag: 'Declined', heading: 'This one did not work out',
    lines: [hi, `Your request for the ${tool} (${dates}) was declined, or the dates were taken by another loan.`, 'Other neighbors may have something similar on the wall.'],
    cta: 'Browse the tool wall', path: '/app',
  },
  cancelled: {
    subject: `Request cancelled: ${p.toolName}`,
    tag: 'Cancelled', heading: 'A request was withdrawn',
    lines: [hi, `${who} cancelled their request for your ${tool} (${dates}). Nothing to do.`],
    cta: 'Open Incoming', path: '/app/incoming',
  },
  returned: {
    subject: `Returned: ${p.toolName}`,
    tag: 'Returned', heading: 'Loan closed',
    lines: [hi, `${who} marked the ${tool} as returned. Thanks for bringing it back.`],
    cta: 'See your requests', path: '/app/requests',
  },
};

const t = templates[p.event];
if (!t) throw new Error(`Unknown event: ${p.event}`);
const href = `${appUrl}${t.path}`;

return [{
  json: {
    deliveryId: p.deliveryId,
    idempotencyKey: `notify:${p.deliveryId}`,
    email: {
      from: $env.RESEND_FROM,
      to: [p.recipient.email],
      subject: t.subject,
      html: layout({ ...t, href }),
      text: toText({ ...t, href }),
    },
  },
}];
